query:
UPDATE course_lessons SET content = REPLACE(content, 
  'Category 2: A controlled stop with power left available to the machine actuators. (Note: Category 2 is rarely used for Emergency Stops, as power remains applied).',
  'Category 2: A controlled stop with power left available to the machine actuators. **IMPORTANT: Category 2 is NOT permitted for Emergency Stops per NFPA 79 and IEC 60204-1.** Emergency stops must be Category 0 or Category 1 only, as power must be removed after the stop is achieved.'
) WHERE id = 120024;

